for f in sorted(I18N.glob('*.json')):
    kod = f.stem
    d = json.loads(f.read_text())
    ui = {}
    if kod != 'sv':
        loc = json.loads((LOC / f'{kod}.json').read_text())
        for s in FRAN_WEBBLASAREN:
            assert s in loc, (kod, s)
            ui[s] = loc[s]
        assert len(T[kod]) == len(EGNA), kod
        ui.update(zip(EGNA, T[kod]))
    # Svenska: fraserna är nycklarna själva (T() faller tillbaka på nyckeln)
    d['proxy.ui'] = json.dumps(ui, ensure_ascii=False, separators=(',', ':')).replace('<', '\\u003c')
    f.write_text(json.dumps(d, ensure_ascii=False, indent=2) + '\n')
print('proxy.ui skrivet för', len(list(I18N.glob('*.json'))), 'språk')
